const state={summary:null,financial:null,stockout:[],overstock:[],slow:[],anomalies:[],transfers:[],copilot:null};
const $=(s)=>document.querySelector(s), $$=(s)=>[...document.querySelectorAll(s)];
const money=(v)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(v||0));
const num=(v,d=2)=>v==null?'—':new Intl.NumberFormat('en-IN',{maximumFractionDigits:d}).format(Number(v));
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
async function api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});if(!r.ok){let x={};try{x=await r.json()}catch{}throw new Error(x.detail||`Request failed (${r.status})`)}return r.json()}
function badge(s){const k=String(s||'unknown').toLowerCase();return `<span class="severity ${esc(k)}">${esc(k)}</span>`}
function goto(page){$$('.page').forEach(x=>x.classList.remove('active'));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$(`#page-${page}`).classList.add('active');$('#page-title').textContent=({overview:'Overview',inventory:'Inventory',sales:'Sales Signals',transfers:'Smart Transfers',twin:'Decision Twin',financial:'Financial Impact',copilot:'AI Copilot'})[page]||page;window.scrollTo({top:0,behavior:'smooth'})}
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>goto(b.dataset.page)));$$('[data-goto]').forEach(b=>b.addEventListener('click',()=>goto(b.dataset.goto)));
function metricCard(icon,cls,label,value,note,badgeText='LIVE'){return `<div class="metric-card"><div class="metric-top"><div class="metric-icon ${cls}">${icon}</div><span class="metric-badge">${badgeText}</span></div><div class="metric-value">${value}</div><div class="metric-label">${label}</div><div class="metric-note">${note}</div></div>`}
function renderOverview(){const s=state.summary,f=state.financial;if(!s)return;$('#analysis-date').textContent=s.analysis_date;const critical=s.inventory.stockout_risk.critical,high=s.inventory.stockout_risk.high;$('#overview-metrics').innerHTML=[metricCard('₹','purple','30-day revenue',money(s.sales.revenue),`${num(s.sales.units_sold,0)} units sold`),metricCard('!','red','Stockout attention',num(critical+high,0),`${critical} critical · ${high} high`),metricCard('✓','green','Inventory health',num(s.inventory.average_health_score,1),`Average score / 100`),metricCard('⇄','amber','Transfer opportunities',f?num(f.smart_transfer.recommendations,0):'—',f?`${money(f.smart_transfer.near_term_cash_purchase_deferred)} purchase cash deferred`:'Loading financial impact')].join('');const risk=s.inventory.stockout_risk;const keys=['critical','high','watch','unknown'];const max=Math.max(1,...keys.map(k=>risk[k]||0));$('#risk-bars').innerHTML=keys.map(k=>`<div class="risk-row"><span>${k}</span><div class="bar-track"><div class="bar-fill ${k}" style="width:${Math.max(4,(risk[k]||0)/max*100)}%"></div></div><strong>${risk[k]||0}</strong></div>`).join('');$('#attention-count').textContent=`Top ${s.attention.length} findings`;$('#attention-list').innerHTML=s.attention.map(a=>`<div class="attention-item"><span class="sev-dot ${esc(a.severity)}"></span><div><strong>${esc(a.product_name)}</strong><small>${esc(a.store_name)}</small></div><div>${badge(a.severity)}</div><div class="hide-mobile"><strong>${a.headline_metric==null?'—':num(a.headline_metric)}</strong><small>${esc(a.headline_metric_name.replaceAll('_',' '))}</small></div><small class="hide-mobile">${esc(a.reason)}</small></div>`).join('')||'<div class="empty">No attention items.</div>'}
function renderInventory(type='stockout'){const tabs=$$('#inventory-tabs .tab');tabs.forEach(t=>t.classList.toggle('active',t.dataset.inv===type));let head='',rows='';if(type==='stockout'){head='<tr><th>Product</th><th>Store</th><th>Risk</th><th>Stock</th><th>Avg/day</th><th>Days cover</th><th>Lead time</th><th>Reorder</th><th>Reason</th></tr>';rows=state.stockout.slice(0,40).map(i=>`<tr><td><strong>${esc(i.product_name)}</strong><span class="muted">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td>${badge(i.risk)}</td><td class="number">${num(i.current_stock,0)}</td><td class="number">${num(i.avg_daily_sales)}</td><td class="number">${num(i.days_cover)}</td><td class="number">${num(i.lead_time_days,0)} d</td><td class="number">${i.recommended_reorder_qty==null?'—':num(i.recommended_reorder_qty,0)}</td><td>${esc(i.reason)}</td></tr>`).join('')}else if(type==='overstock'){head='<tr><th>Product</th><th>Store</th><th>Severity</th><th>Stock</th><th>30d sales</th><th>Avg/day</th><th>Days cover</th><th>Reason</th></tr>';rows=state.overstock.slice(0,40).map(i=>`<tr><td><strong>${esc(i.product_name)}</strong><span class="muted">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td>${badge(i.severity)}</td><td class="number">${num(i.current_stock,0)}</td><td class="number">${num(i.units_sold,0)}</td><td class="number">${num(i.avg_daily_sales)}</td><td class="number">${num(i.days_cover)}</td><td>${esc(i.reason)}</td></tr>`).join('')}else{head='<tr><th>Product</th><th>Store</th><th>Stock</th><th>30d sales</th><th>Avg/day</th><th>Days cover</th><th>Reason</th></tr>';rows=state.slow.slice(0,40).map(i=>`<tr><td><strong>${esc(i.product_name)}</strong><span class="muted">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td class="number">${num(i.current_stock,0)}</td><td class="number">${num(i.units_sold,0)}</td><td class="number">${num(i.avg_daily_sales)}</td><td class="number">${num(i.days_cover)}</td><td>${esc(i.reason)}</td></tr>`).join('')}$('#inventory-head').innerHTML=head;$('#inventory-body').innerHTML=rows||'<tr><td colspan="9" class="empty">No matching findings.</td></tr>'}
$$('#inventory-tabs .tab').forEach(t=>t.addEventListener('click',()=>renderInventory(t.dataset.inv)));
function renderSales(){const a=state.anomalies;const spikes=a.filter(x=>x.anomaly_type==='spike').length,drops=a.filter(x=>x.anomaly_type==='drop').length;$('#signal-summary').innerHTML=`<div class="signal-card spike"><div class="signal-icon">↑</div><div><strong>${spikes}</strong><span>Demand spikes detected</span></div></div><div class="signal-card drop"><div class="signal-icon">↓</div><div><strong>${drops}</strong><span>Demand drops detected</span></div></div>`;$('#sales-body').innerHTML=a.map(i=>`<tr><td><strong>${esc(i.product_name)}</strong><span class="muted">${esc(i.product_id)}</span></td><td>${esc(i.store_name)}</td><td>${badge(i.anomaly_type)}</td><td class="number">${num(i.recent_avg_daily_sales)}</td><td class="number">${num(i.baseline_avg_daily_sales)}</td><td class="number change ${i.percentage_change>=0?'up':'down'}">${i.percentage_change>=0?'+':''}${num(i.percentage_change,1)}%</td><td>${esc(i.reason)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No anomalies detected.</td></tr>'}
function renderTransfers(){const list=state.transfers;$('#transfer-list').innerHTML=list.map(i=>`<article class="transfer-card"><div class="panel-head"><div><p class="eyebrow">${esc(i.product_id)} · ${esc(i.category)}</p><h3>${esc(i.product_name)}</h3></div>${badge(i.recipient_risk)}</div><div class="transfer-route"><div class="store-node"><div class="label">Source</div><strong>${esc(i.recommended_source_store_name)}</strong><span>Donor cover after: ${num(i.donor_after_days_cover)} days</span></div><div class="route-arrow">→</div><div class="store-node"><div class="label">Recipient</div><strong>${esc(i.recipient_store_name)}</strong><span>${num(i.recipient_current_stock,0)} units · ${num(i.recipient_days_cover)} days cover</span></div></div><div class="transfer-meta"><span class="meta-chip">Move <strong>${num(i.recommended_transfer_quantity,0)} units</strong></span><span class="meta-chip">After cover <strong>${num(i.recipient_after_days_cover)} d</strong></span><span class="meta-chip">Transfer cost <strong>${money(i.estimated_transfer_cost)}</strong></span><span class="meta-chip">Purchase deferred <strong>${money(i.near_term_purchase_deferred)}</strong></span></div></article>`).join('')||'<div class="panel empty">No safe transfer recommendations.</div>'}
function renderFinancial(){const f=state.financial;if(!f)return;$('#financial-metrics').innerHTML=[metricCard('!','red','Revenue at risk',money(f.stockout_exposure.revenue_at_risk),`${f.stockout_exposure.products} exposed product-store pairs`),metricCard('▣','amber','Blocked capital',money(f.overstock_exposure.blocked_capital_at_cost),`${f.overstock_exposure.products} overstock exposures`),metricCard('⇄','green','Revenue protected',money(f.smart_transfer.estimated_revenue_protected),`${f.smart_transfer.recommendations} safe transfer opportunities`),metricCard('₹','purple','Purchase cash deferred',money(f.smart_transfer.near_term_cash_purchase_deferred),`By rebalancing existing stock`)].join('');$('#stockout-money').innerHTML=`<div class="money-row"><span>Revenue at risk</span><strong>${money(f.stockout_exposure.revenue_at_risk)}</strong></div><div class="money-row"><span>Gross margin at risk</span><strong>${money(f.stockout_exposure.gross_margin_at_risk)}</strong></div><div class="money-row"><span>Retail value of excess</span><strong>${money(f.overstock_exposure.retail_value_of_excess)}</strong></div>`;$('#transfer-money').innerHTML=`<div class="money-row"><span>Estimated transfer cost</span><strong>${money(f.smart_transfer.estimated_transfer_cost)}</strong></div><div class="money-row"><span>Gross margin protected</span><strong>${money(f.smart_transfer.estimated_gross_margin_protected)}</strong></div><div class="money-row"><span>Net operational benefit</span><strong>${money(f.smart_transfer.estimated_net_operational_benefit)}</strong></div>`;$('#financial-disclaimer').textContent=f.disclaimer}
async function runTwin(){const store=$('#twin-store').value.trim(),product=$('#twin-product').value.trim(),h=Number($('#twin-horizon').value||14),m=Number($('#twin-demand').value||1);const btn=$('#run-twin');btn.disabled=true;btn.textContent='Simulating…';try{const r=await api(`/api/simulation/compare?store_id=${encodeURIComponent(store)}&product_id=${encodeURIComponent(product)}&horizon_days=${h}&demand_multiplier=${m}`);renderTwin(r)}catch(e){toast(e.message);$('#scenario-grid').innerHTML=`<div class="panel empty">${esc(e.message)}</div>`}finally{btn.disabled=false;btn.textContent='Run simulation'}}
function renderTwin(r){if(r.status!=='ok'){const msg=r.message||'Insufficient data for a reliable simulation.';$('#twin-current').innerHTML='';$('#scenario-grid').innerHTML=`<div class="panel empty">${esc(msg)}</div>`;$('#twin-recommendation').innerHTML=`<h3>Simulation withheld</h3><p>${esc(msg)}</p>`;return}const c=r.current_state;$('#twin-current').innerHTML=[['Risk',c.risk],['Current stock',num(c.current_stock,0)],['Avg demand/day',num(c.avg_daily_sales)],['Days cover',num(c.days_cover)],['Reorder qty',num(c.recommended_reorder_qty,0)]].map(([a,b])=>`<div class="state-pill"><span>${a}</span><strong>${b}</strong></div>`).join('');const rec=r.comparison.recommended_scenario_id;$('#scenario-grid').innerHTML=r.scenarios.map(s=>`<article class="scenario-card ${s.scenario_id===rec?'recommended':''}">${s.scenario_id===rec?'<span class="rec-ribbon">RECOMMENDED</span>':''}<h3>${esc(s.label)}</h3><span class="sub">${num(s.horizon_days,0)}-day scenario</span><div class="service-meter"><div style="width:${Math.max(0,Math.min(100,s.service_level_pct||0))}%"></div></div><span class="sub">${num(s.service_level_pct,1)}% service level</span><div class="scenario-kpis"><div class="scenario-kpi"><span>Unserved</span><strong>${num(s.unserved_units,0)} units</strong></div><div class="scenario-kpi"><span>Ending stock</span><strong>${num(s.ending_stock,0)}</strong></div><div class="scenario-kpi"><span>Operating loss</span><strong>${money(s.estimated_operational_loss)}</strong></div><div class="scenario-kpi"><span>Cash committed</span><strong>${money(s.cash_committed)}</strong></div></div></article>`).join('');$('#twin-recommendation').innerHTML=`<p class="eyebrow">DECISION SUPPORT</p><h3>${esc(r.comparison.recommendation)}</h3><p>${esc(r.comparison.reason)} ${esc(r.comparison.human_decision_note)}</p>`}
$('#run-twin').addEventListener('click',runTwin);
function addMessage(role,text,meta=[]){const chat=$('#chat'),el=document.createElement('div');el.className=`message ${role}`;el.innerHTML=`<div class="avatar">${role==='user'?'Y':'R'}</div><div class="bubble">${role==='assistant'?'<strong>RetailIQ Copilot</strong>':''}<p>${esc(text)}</p>${meta.length?`<div class="msg-meta">${meta.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}</div>`;chat.appendChild(el);chat.scrollTop=chat.scrollHeight}
function renderEvidence(r){const ev=(r.evidence||[]).slice(0,8);const guards=r.safeguards||{};$('#evidence-content').innerHTML=`<div class="evidence-block"><h4>Routing</h4><code>intent: ${esc(r.intent)}</code><code>tool: ${esc(r.tool||'—')}</code><code>mode: ${esc(r.mode)}</code></div><div class="evidence-block"><h4>Source records</h4>${ev.map(e=>`<code>${esc(e.citation_id||'E')} · ${esc(e.source)} · ${(e.record_ids||[]).length} record(s)</code>`).join('')||'<span class="muted">No record citations.</span>'}</div><div class="evidence-block"><h4>Unknowns</h4>${(r.unknowns||[]).map(x=>`<code>${esc(x)}</code>`).join('')||'<span class="muted">No unresolved data fields.</span>'}</div><div class="evidence-block"><h4>Safeguards</h4><div class="guard-row"><span>LLM calculates metrics</span><span>${guards.llm_calculates_metrics?'YES':'NO'}</span></div><div class="guard-row"><span>LLM executes actions</span><span>${guards.llm_executes_actions?'YES':'NO'}</span></div><div class="guard-row"><span>Unsupported numbers rejected</span><span>${guards.unsupported_numbers_rejected?'ON':'OFF'}</span></div><div class="guard-row"><span>Causal inference without evidence</span><span>${guards.causal_inference_without_evidence?'ON':'OFF'}</span></div></div>`}
async function askCopilot(message){const input=$('#copilot-input'),lang=$('#copilot-language').value;addMessage('user',message);input.value='';input.disabled=true;try{const r=await api('/api/copilot/query',{method:'POST',body:JSON.stringify({message,language:lang||null})});state.copilot=r;addMessage('assistant',r.answer||'No answer returned.',[r.intent||'unknown',r.mode||'unknown',r.human_review_required?'human review':'grounded']);renderEvidence(r)}catch(e){addMessage('assistant',`I could not complete that request: ${e.message}`);toast(e.message)}finally{input.disabled=false;input.focus()}}
$('#copilot-form').addEventListener('submit',e=>{e.preventDefault();const m=$('#copilot-input').value.trim();if(m)askCopilot(m)});$$('#quick-prompts button').forEach(b=>b.addEventListener('click',()=>{$('#copilot-input').value=b.textContent;askCopilot(b.textContent)}));
async function loadCopilotStatus(){try{const s=await api('/api/copilot/status');const e=$('#model-status');e.textContent=s.gemini_configured?`${s.model} · grounded`:`${s.model} · fallback ready`;e.classList.add('ready')}catch{$('#model-status').textContent='Fallback ready'}}
async function loadAll(){const refresh=$('#refresh-btn');refresh.disabled=true;try{const [summary,financial,stockout,overstock,slow,anomalies,transfers]=await Promise.all([api('/api/dashboard/summary'),api('/api/financial/summary'),api('/api/inventory/stockout-risk?limit=150'),api('/api/inventory/overstock?limit=150'),api('/api/inventory/slow-movers?limit=150'),api('/api/sales/anomalies?limit=150'),api('/api/transfers/recommendations?limit=50')]);state.summary=summary;state.financial=financial;state.stockout=stockout.items||[];state.overstock=overstock.items||[];state.slow=slow.items||[];state.anomalies=anomalies.items||[];state.transfers=transfers.items||[];renderOverview();renderInventory();renderSales();renderTransfers();renderFinancial();$('#api-status').classList.add('online');$('#api-status').innerHTML='<span class="status-dot"></span>Live data';toast('Retail data refreshed')}catch(e){$('#api-status').innerHTML='<span class="status-dot"></span>Degraded';toast(e.message)}finally{refresh.disabled=false}}
$('#refresh-btn').addEventListener('click',loadAll);
loadAll();loadCopilotStatus();runTwin();
